// ══════════ src/mask.js ══════════
// GENERATED by scripts/generate-mask.js — do not edit by hand.
// Land bitmask, 512×256 equirectangular cells (row-major from
// lat +90 down, lon −180 → +180), 1 bit per cell, base64-packed.
// Data: Natural Earth 110m land (public domain, naturalearthdata.com).

export const MASK_W = 512;
export const MASK_H = 256;

const BITS = /* base64 */ Uint8Array.from(atob(""), (c) => c.charCodeAt(0));

// Is there land at this latitude/longitude? The single primitive the whole
// renderer derives from.
export function isLand(lat, lon) {
  if (lat > 90 || lat < -90) return false;
  const col = Math.min(MASK_W - 1, Math.max(0, Math.floor(((lon + 180) / 360) * MASK_W)));
  const row = Math.min(MASK_H - 1, Math.max(0, Math.floor(((90 - lat) / 180) * MASK_H)));
  const idx = row * MASK_W + col;
  return (BITS[idx >> 3] & (1 << (idx & 7))) !== 0;
}

// ══════════ src/projection.js ══════════
// Equirectangular projection — the deliberate choice for a SYMBOLIC map:
// linear lat/lon ↔ x/y, matching both the packed land mask and everyone's
// mental image of "the world map". Not area-accurate (Mercator-style debates
// don't apply — nothing here encodes quantity by area).
//
// All renderer geometry flows through these two functions, which is what
// makes the future globe mode a renderer swap instead of an API change:
// callers speak lat/lon, only the projection changes.

// Map a lat/lon to fractional grid coordinates in a cols×rows grid covering
// latRange (north→south) across the full −180…180 longitude span.
export function project(lat, lon, { cols, rows, latRange }) {
  const [latMin, latMax] = latRange;
  return {
    x: ((lon + 180) / 360) * cols,
    y: ((latMax - lat) / (latMax - latMin)) * rows
  };
}

// The center lat/lon of a grid cell — where the mask is sampled and where a
// dot is drawn.
export function cellCenter(col, row, { cols, rows, latRange }) {
  const [latMin, latMax] = latRange;
  return {
    lat: latMax - ((row + 0.5) / rows) * (latMax - latMin),
    lon: -180 + ((col + 0.5) / cols) * 360
  };
}

// ══════════ src/noise.js ══════════
// Compact 2D value noise — smooth, deterministic, zero-dependency. Used to
// shape ambient animation DELAY fields (ambient: "noise"): neighboring dots
// get neighboring phases, so the matrix shimmers in organic patches instead
// of mechanical sweeps. Not full simplex noise — for picking per-dot delays
// once at render time, smooth value noise is indistinguishable and a third
// of the code. If a future time-evolving mode needs higher-quality gradients,
// swap the internals; the noise2(x, y) → [-1, 1] contract holds.

// Deterministic integer hash → [0, 1). Same input, same output, every load —
// re-renders must not reshuffle the field.
function hash(ix, iy) {
  let h = (ix * 374761393 + iy * 668265263) | 0; // large primes
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

// Quintic smoothstep — C2-continuous interpolation, no grid-line artifacts.
function fade(t) {
  return t * t * t * (t * (t * 6 - 15) + 10);
}

// @return [Number] smooth noise in [-1, 1]
export function noise2(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y);
  const fx = x - ix, fy = y - iy;

  const a = hash(ix, iy);
  const b = hash(ix + 1, iy);
  const c = hash(ix, iy + 1);
  const d = hash(ix + 1, iy + 1);

  const ux = fade(fx), uy = fade(fy);
  const value = a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
  return value * 2 - 1;
}

